import { AbsoluteFill, Img, useCurrentFrame } from "remotion";
import { ANTON, Anchor, Art, BG, Bg, Col, Cursor, L, LIME, MONO, PEN_FPS, Tr, TrKind, WHITE, asset, bump, glow, io, k, lin, mix, pop, v } from "./base";
import { Hook, Hundred, Intro } from "./abertura";
import { Arsenal, Custom } from "./meio";

export { PEN_FPS, PEN_FRAMES } from "./base";

const ROW_A = [1, 9, 15, 19, 23, 27, 12];
const ROW_B = [2, 16, 20, 25, 7, 34, 18];
const Belt: React.FC<{ t: number; y: number; dir: number; list: number[]; o: number }> = ({ t, y, dir, list, o }) => {
  const w = 300;
  const step = w + 24;
  const loop = step * list.length;
  const off = (((t * 130 * dir) % loop) + loop) % loop;
  return (
    <div style={{ position: "absolute", left: -off, top: y, display: "flex", gap: 24, opacity: o, filter: "brightness(0.5)" }}>
      {[...list, ...list, ...list.slice(0, 4)].map((n, i) => (
        <Art key={i} n={n} w={w} style={{ flexShrink: 0 }} />
      ))}
    </div>
  );
};
// ───────── cena 6: a oferta — os itens se juntam e viram a etiqueta do preço ─────────
const ITEMS = ["+100 PSDs", "Elementos PNG", "Texturas", "+70 fontes", "Aulas práticas", "Prospecção"];
const Offer: React.FC<{ t: number }> = ({ t }) => {
  const a = 19.7;
  const hit = v(20.72) - 0.02;
  if (t < hit) {
    const g = io(t, hit - 0.24, 0.24);
    return (
      <>
        <Bg t={t} y={48} a={0.14} />
        <Col top={330}>
          <L t={t} size={236} words={[["Tudo", 19.62], ["isso", 19.84]]} />
        </Col>
        <div style={{ position: "absolute", left: 120, top: 700, width: 840, height: 400 }}>
          {ITEMS.map((s, i) => {
            const p = pop(t, a + 0.06 + i * 0.07, 0.28);
            const x = (i % 2) * 430;
            const y = Math.floor(i / 2) * 136;
            return (
              <div key={s} style={{ position: "absolute", left: mix(x, 215, g), top: mix(y, 136, g), width: 410, height: 112, borderRadius: 20, boxSizing: "border-box", border: `3px solid ${LIME}`, background: "#0C0C0C", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: ANTON, fontSize: 50, color: WHITE, textTransform: "uppercase", letterSpacing: "0.01em", whiteSpace: "nowrap", transform: `scale(${(p * (1 - g * 0.5)).toFixed(3)})`, opacity: Math.min(1, p * 3) * (1 - g) }}>{s}</div>
            );
          })}
        </div>
        <Col top={1180}>
          <L t={t} size={138} color={LIME} words={[["por", 20.14], ["apenas", 20.28]]} />
        </Col>
      </>
    );
  }
  const e = k(t, hit, 0.3);
  const roll = t < hit + 0.3;
  const dg = (i: number, final: string) => (roll ? String(Math.floor((t * 60 + i * 3) * 7) % 10) : final);
  const sk = t < hit + 0.4 ? 14 * (1 - (t - hit) / 0.4) : 0;
  const sweep = ((t - hit - 0.75) % 1.7) / 0.6;
  const rows: [number, string, string][] = [
    [v(22.55) - 0.1, "1×", "PAGA UMA ÚNICA VEZ"],
    [v(23.89) - 0.08, "∞", "ACESSO VITALÍCIO"],
  ];
  return (
    <>
      <Bg t={t} y={38} a={0.2} />
      <Belt t={t} y={1530} dir={-1} list={ROW_A} o={k(t, hit + 0.2, 0.6)} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(7,7,7,1) 78%, rgba(7,7,7,0) 90%)" }} />
      {[0, 0.14].map((dl) => {
        const u = k(t, hit + dl, 0.8);
        return u > 0 && u < 1 ? <div key={dl} style={{ position: "absolute", left: 120, top: 520, width: 840, height: 440, borderRadius: 60, border: `${(14 * (1 - u)).toFixed(1)}px solid ${LIME}`, boxSizing: "border-box", transform: `scale(${(1 + u * 0.7).toFixed(3)})`, opacity: 1 - u }} /> : null;
      })}
      <div style={{ position: "absolute", left: 0, right: 0, top: 400, textAlign: "center", fontFamily: ANTON, fontSize: 78, lineHeight: 1.1, color: WHITE, letterSpacing: "0.02em", opacity: k(t, hit + 0.1, 0.25) }}>TUDO ISSO POR APENAS</div>
      <div style={{ position: "absolute", left: 120, top: 520, width: 840, height: 440, transform: `translate(${(Math.sin(t * 83) * sk).toFixed(1)}px, ${(Math.cos(t * 71) * sk).toFixed(1)}px) scale(${(1 + (1 - e) * 0.9).toFixed(4)})`, opacity: k(t, hit, 0.06) }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 44, background: LIME, boxShadow: glow(LIME, 1.5), overflow: "hidden" }}>
          {sweep > 0 && sweep < 1 && !roll ? <div style={{ position: "absolute", left: -300 + sweep * 1400, top: -60, width: 150, height: 560, background: "rgba(255,255,255,0.45)", transform: "skewX(-20deg)" }} /> : null}
          <div style={{ position: "absolute", inset: 0, display: "flex", justifyContent: "center", alignItems: "flex-start", fontFamily: ANTON, color: "#000", paddingTop: 34 }}>
            <span style={{ fontSize: 96, lineHeight: 1, marginTop: 30, marginRight: 6 }}>R$</span>
            <span style={{ fontSize: 360, lineHeight: 0.98, width: 400, textAlign: "center" }}>
              {dg(0, "3")}
              {dg(1, "7")}
            </span>
            <span style={{ fontSize: 160, lineHeight: 1, marginTop: 26, width: 205 }}>
              ,{dg(2, "9")}
              {dg(3, "0")}
            </span>
          </div>
        </div>
        {[[0, 0], [840, 0], [840, 440], [0, 440]].map(([x, y], i) => (
          <Anchor key={i} x={x} y={y} p={pop(t, hit + 0.2 + i * 0.07, 0.25)} s={34} />
        ))}
      </div>
      {rows.map(([at, ic, txt], i) => (
        <div key={txt} style={{ position: "absolute", left: 120, top: 1060 + i * 150, width: 840, height: 124, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", gap: 24, background: "#0C0C0C", border: `4px solid ${LIME}`, borderRadius: 26, fontFamily: ANTON, fontSize: 80, lineHeight: 1, color: WHITE, whiteSpace: "nowrap", opacity: k(t, at, 0.1), transform: `scale(${(0.7 + 0.3 * pop(t, at, 0.35) + bump(t, at + 0.55, 0.04)).toFixed(3)})`, boxShadow: t < at + 0.9 ? glow(LIME, 0.7) : undefined }}>
          <span style={{ color: LIME, fontFamily: MONO, fontWeight: 700, fontSize: 72 }}>{ic}</span>
          {txt}
        </div>
      ))}
      <div style={{ position: "absolute", left: 0, right: 0, top: 1396, display: "flex", justifyContent: "center", alignItems: "center", gap: 16, fontFamily: MONO, fontWeight: 700, fontSize: 42, lineHeight: 1, color: WHITE, letterSpacing: "0.04em", opacity: k(t, 24.55, 0.25), transform: `scale(${(0.8 + 0.2 * pop(t, 24.55, 0.35)).toFixed(3)})` }}>
        <svg width={52} height={58} viewBox="0 0 24 26" fill="none" stroke={LIME} strokeWidth={2.6} strokeLinecap="round" strokeLinejoin="round">
          <path d="M12 2l9 3.5v7c0 6-4 9.5-9 11.5-5-2-9-5.5-9-11.5v-7z" />
          <path d="M7.5 12.5l3.2 3.2 5.8-6.2" />
        </svg>
        7 DIAS DE GARANTIA
      </div>
    </>
  );
};

// ───────── cena 7: o "0" do começo é coberto por um leque de artes; depois logo, botão e preço entre duas esteiras ─────────
const FAN = [21, 13, 29, 3, 6];
const Cta: React.FC<{ t: number }> = ({ t }) => {
  const a = 25.25;
  const b = 26.72;
  if (t < b) {
    const W = 340;
    return (
      <>
        <Bg t={t} y={62} a={0.16} />
        <Col top={270}>
          <L t={t} size={128} words={[["Chega", 25.15], ["de", 25.43]]} />
          <div style={{ position: "relative" }}>
            <L t={t} size={128} words={[["começar", 25.53], ["do", 25.97], ["zero", 26.09]]} />
            <div style={{ position: "absolute", left: -16, right: -16, top: "50%", height: 18, background: LIME, boxShadow: glow(LIME, 0.8), transform: `scaleX(${io(t, v(26.09) + 0.18, 0.22)})`, transformOrigin: "0 50%" }} />
          </div>
        </Col>
        <svg width={600} height={760} viewBox="-300 -380 600 760" style={{ position: "absolute", left: 240, top: 1150 - 380, opacity: 0.5 * (1 - k(t, a + 0.5, 0.5)) }}>
          <ellipse rx={215} ry={315} fill="none" stroke={LIME} strokeWidth={10} />
        </svg>
        <div style={{ position: "absolute", left: 540, top: 1500, width: 0, height: 0, transform: `scale(${(1 + lin(t, a, b) * 0.05).toFixed(4)})` }}>
          {FAN.map((n, i) => {
            const at = a + 0.28 + i * 0.16;
            const e = pop(t, at, 0.35);
            const ang = (i - 2) * 11.5 * e;
            return t < at ? null : (
              <div key={n} style={{ position: "absolute", left: -W / 2, top: -W * 1.25 - 120, transformOrigin: `50% ${W * 1.25 + 420}px`, transform: `rotate(${ang.toFixed(2)}deg) scale(${(0.5 + 0.5 * e).toFixed(3)})`, zIndex: i === 2 ? 5 : 4 - Math.abs(i - 2) }}>
                <Art n={n} w={W} style={{ border: `4px solid ${LIME}`, boxShadow: "0 30px 60px rgba(0,0,0,0.7)" }} />
              </div>
            );
          })}
        </div>
      </>
    );
  }
  const click = v(26.91) + 0.16;
  const press = t > click && t < click + 0.16 ? 0.93 : 1;
  const o = k(t, b, 0.5);
  return (
    <>
      <Bg t={t} y={44} a={0.18} />
      <Belt t={t} y={90} dir={1} list={ROW_A} o={o} />
      <Belt t={t} y={1520} dir={-1} list={ROW_B} o={o} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(7,7,7,0) 14%, rgba(7,7,7,1) 27%, rgba(7,7,7,1) 77%, rgba(7,7,7,0) 90%)" }} />
      <Img src={asset("logo.png")} style={{ position: "absolute", left: 150, top: 520, width: 780, opacity: k(t, b, 0.1), transform: `scale(${(1 + (1 - k(t, b, 0.35)) * 0.6 + bump(t, v(28.21), 0.05)).toFixed(3)})`, filter: `drop-shadow(0 0 ${(16 + 12 * Math.abs(Math.sin(t * 4))).toFixed(0)}px rgba(155,255,0,0.45))` }} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 1010, display: "flex", justifyContent: "center" }}>
        <div style={{ position: "relative", transform: `scale(${(pop(t, b + 0.12, 0.4) * press).toFixed(4)})` }}>
          <div style={{ background: LIME, color: "#000", fontFamily: ANTON, fontSize: 92, borderRadius: 28, padding: "14px 56px", boxShadow: `${glow(LIME, 1.1)}, 0 12px 0 #4E8000`, whiteSpace: "nowrap", letterSpacing: "0.01em" }}>QUERO MEU ACESSO</div>
          {[0, 0.5].map((dl) => {
            const u = t > click ? (t - click + dl) % 1 : -1;
            return u >= 0 ? <div key={dl} style={{ position: "absolute", inset: -6, borderRadius: 36, border: `6px solid ${LIME}`, opacity: 0.6 * (1 - u), transform: `scale(${(1 + u * 0.14).toFixed(3)}, ${(1 + u * 0.45).toFixed(3)})` }} /> : null;
          })}
        </div>
      </div>
      <Cursor x={mix(1150, 720, io(t, b + 0.15, 0.4))} y={mix(1500, 1100, io(t, b + 0.15, 0.4)) + (press < 1 ? 8 : 0)} s={1.7} />
      <Col top={1240} gap={16}>
        <div style={{ fontFamily: ANTON, fontSize: 80, color: WHITE, opacity: k(t, v(27.49), 0.25), transform: `scale(${(0.8 + 0.2 * pop(t, v(27.49), 0.35)).toFixed(3)})`, whiteSpace: "nowrap" }}>
          POR APENAS <span style={{ color: LIME, textShadow: glow(LIME, 0.8) }}>R$ 37,90</span>
        </div>
        <div style={{ fontFamily: MONO, fontWeight: 700, fontSize: 29, color: "#D0D0D0", letterSpacing: "0.02em", whiteSpace: "nowrap", opacity: k(t, v(27.49) + 0.3, 0.4) }}>paga uma vez · acesso vitalício · 7 dias de garantia</div>
      </Col>
    </>
  );
};

// ───────── montagem ─────────
const SCENES: { C: React.FC<{ t: number }>; at: number }[] = [
  { C: Hook, at: 0 },
  { C: Intro, at: 3.2 },
  { C: Hundred, at: 5.4 },
  { C: Custom, at: 8.45 },
  { C: Arsenal, at: 11.3 },
  { C: Offer, at: 19.7 },
  { C: Cta, at: 25.25 },
];
const CUTS: [number, TrKind][] = [
  [3.2, "iris"],
  [5.4, "flash"],
  [8.45, "bars"],
  [9.9, "up"],
  [11.3, "split"],
  [12.2, "hole"],
  [19.7, "drop"],
  [25.25, "doors"],
  [26.72, "flash"],
];
export const PsdEliteNovo: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / PEN_FPS;
  return (
    <AbsoluteFill style={{ background: BG }}>
      {SCENES.map((s, i) => {
        const next = i + 1 < SCENES.length ? SCENES[i + 1].at : 1e9;
        return t >= s.at && t < next ? (
          <AbsoluteFill key={i} style={{ overflow: "hidden" }}>
            <s.C t={t} />
          </AbsoluteFill>
        ) : null;
      })}
      {CUTS.map(([at, kind]) => (
        <Tr key={at} t={t} at={at} kind={kind} />
      ))}
    </AbsoluteFill>
  );
};

import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { AbsoluteFill, Easing, Img, interpolate, staticFile } from "remotion";

// PSD DE ELITE — segunda versão do anúncio de 31 s (12/10): mesma locução e mesmos tempos de fala da primeira
// (PsdElite.tsx), outra encenação. Identidade igual: preto, verde-limão neon, Anton, rótulos em monoespaçada e os pontos
// de âncora da ferramenta caneta do logo. O que muda: abertura em três batidas (nome, relógio, o "0" desenhado a caneta),
// artes vindo em túnel, painel de camadas, versões reais do mesmo PSD, arsenal um item por vez, preço em etiqueta verde.
// Tudo numa coluna central de 840 px; texto entra e fica parado. Sem áudio aqui.

export const { fontFamily: ANTON } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: MONO } = loadMono("normal", { weights: ["500", "700"], subsets: ["latin", "latin-ext"] });

export const PEN_FPS = 30;
export const PEN_FRAMES = 31 * PEN_FPS;
const VO = 0.15;
export const BG = "#070707";
export const LIME = "#9BFF00";
export const WHITE = "#FFFFFF";
export const PANEL = "#151515";
export const EDGE = "#333333";
export const RED = "#FF3B3B";
export const asset = (f: string) => staticFile(`psdelite/${f}`);
export const art = (n: number) => asset(`b${String(n).padStart(2, "0")}.jpg`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.5));
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
export const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;
export const v = (s: number) => s + VO;
export const bump = (t: number, at: number, amt = 0.06, d = 0.4) => (t >= at ? amt * (1 - k(t, at, d)) : 0);
export const glow = (c: string, s = 1) => `0 0 ${(6.5 * s).toFixed(1)}px ${c}, 0 0 ${(24 * s).toFixed(1)}px ${c}`;

// fundo: preto liso com um clarão verde suave atrás do assunto da cena
export const Bg: React.FC<{ t: number; y?: number; a?: number; c?: string }> = ({ t, y = 50, a = 0.16, c = "155,255,0" }) => (
  <AbsoluteFill style={{ background: BG }}>
    <AbsoluteFill style={{ background: `radial-gradient(64% 40% at 50% ${y}%, rgba(${c},${(a * (0.85 + 0.15 * Math.sin(t * 2.2))).toFixed(3)}) 0%, rgba(${c},0) 72%)` }} />
  </AbsoluteFill>
);

// palavras em Anton batendo no tempo da fala: entram com um leve recuo de escala e ficam paradas
export type W = [string, number, string?];
export const L: React.FC<{ t: number; words: W[]; size: number; color?: string; shadow?: boolean }> = ({ t, words, size, color = WHITE, shadow = true }) => (
  <div style={{ display: "flex", justifyContent: "center", alignItems: "baseline", gap: size * 0.26, whiteSpace: "nowrap", fontFamily: ANTON, fontSize: size, lineHeight: 1.06, letterSpacing: "0.01em", textTransform: "uppercase", color }}>
    {words.map(([w, at, c], i) => {
      const e = k(t, v(at) - 0.04, 0.22);
      const col = c ?? color;
      return (
        <span key={i} style={{ display: "inline-block", opacity: k(t, v(at) - 0.04, 0.07), transform: `scale(${(1 + (1 - e) * 0.38).toFixed(3)})`, color: col, textShadow: !shadow ? undefined : col === LIME ? glow(LIME, 0.9) : col === RED ? glow(RED, 0.7) : undefined }}>{w}</span>
      );
    })}
  </div>
);
export const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);
// as artes do pack são 4:5; o cartão tem a mesma proporção, então nada é cortado
export const Art: React.FC<{ n: number; w: number; style?: React.CSSProperties }> = ({ n, w, style }) => (
  <Img src={art(n)} style={{ width: w, height: w * 1.25, objectFit: "cover", borderRadius: w * 0.035, display: "block", ...style }} />
);
export const Cursor: React.FC<{ x: number; y: number; s?: number }> = ({ x, y, s = 1 }) => (
  <svg width={54 * s} height={66 * s} viewBox="0 0 22 27" style={{ position: "absolute", left: x, top: y, filter: "drop-shadow(0 6px 8px rgba(0,0,0,0.6))", zIndex: 8 }}>
    <path d="M2 2 L2 21 L7 16.5 L10.5 24.5 L14 23 L10.5 15 L17.5 15 Z" fill={WHITE} stroke="#000" strokeWidth={1.6} strokeLinejoin="round" />
  </svg>
);
// ponto de âncora da ferramenta caneta
export const Anchor: React.FC<{ x: number; y: number; p?: number; s?: number }> = ({ x, y, p = 1, s = 30 }) => (
  <div style={{ position: "absolute", left: x - s / 2, top: y - s / 2, width: s, height: s, background: WHITE, border: `5px solid ${LIME}`, boxSizing: "border-box", transform: `scale(${p.toFixed(3)})` }} />
);
// a alça do logo: linha com um quadrado no meio e círculos nas pontas
export const Handle: React.FC<{ w: number; p: number; style?: React.CSSProperties }> = ({ w, p, style }) => (
  <div style={{ position: "relative", width: w, height: 36, ...style }}>
    <div style={{ position: "absolute", left: 0, right: 0, top: 15, height: 6, background: LIME, transform: `scaleX(${p})`, boxShadow: glow(LIME, 0.5) }} />
    {[0, w - 32].map((x, i) => (
      <div key={i} style={{ position: "absolute", left: x, top: 2, width: 32, height: 32, borderRadius: 16, background: LIME, transform: `scale(${p > 0.95 ? 1 : 0})` }} />
    ))}
    <div style={{ position: "absolute", left: w / 2 - 18, top: 0, width: 36, height: 36, borderRadius: 6, background: LIME, transform: `scale(${Math.min(1, p * 3)})` }} />
  </div>
);

// ───────── transições: uma diferente a cada troca de cena ─────────
export type TrKind = "iris" | "flash" | "bars" | "up" | "split" | "hole" | "drop" | "doors";
const holeMask = (r: number, cy: number): React.CSSProperties => {
  const m = `radial-gradient(circle at 50% ${cy}%, transparent ${r.toFixed(0)}px, #000 ${(r + 3).toFixed(0)}px)`;
  return { WebkitMaskImage: m, maskImage: m };
};
export const Tr: React.FC<{ t: number; at: number; kind: TrKind }> = ({ t, at, kind }) => {
  if (t < at - 0.3 || t > at + 0.4) return null;
  const a = io(t, at - 0.26, 0.26);
  const b = io(t, at, 0.3);
  const z: React.CSSProperties = { zIndex: 30, overflow: "hidden", pointerEvents: "none" };
  if (kind === "flash") return <AbsoluteFill style={{ ...z, background: LIME, opacity: t < at ? a * 0.9 : 0.9 * (1 - k(t, at, 0.25)) }} />;
  if (kind === "iris")
    return (
      <AbsoluteFill style={z}>
        {t < at ? <div style={{ position: "absolute", left: 540 - 1150, top: 960 - 1150, width: 2300, height: 2300, borderRadius: 1150, background: LIME, transform: `scale(${a.toFixed(4)})` }} /> : <AbsoluteFill style={{ background: LIME, ...holeMask(b * 1150, 50) }} />}
      </AbsoluteFill>
    );
  if (kind === "hole") return t < at ? null : <AbsoluteFill style={{ ...z, background: LIME, ...holeMask(b * 1250, 46) }} />;
  if (kind === "bars" || kind === "drop")
    return (
      <AbsoluteFill style={z}>
        {[0, 1, 2, 3].map((i) => {
          const p = io(t, at - 0.28 + i * 0.03, 0.24);
          const q = io(t, at + i * 0.03, 0.26);
          const y = kind === "bars" ? mix(1920, 0, p) - q * 1920 : mix(-1920, 0, p) + q * 1920;
          return <div key={i} style={{ position: "absolute", left: i * 270, top: y, width: 271, height: 1920, background: i % 2 ? "#0E1A00" : LIME }} />;
        })}
      </AbsoluteFill>
    );
  if (kind === "up")
    return (
      <AbsoluteFill style={z}>
        <div style={{ position: "absolute", left: 0, top: mix(1920, 0, a) - b * 1920, width: 1080, height: 1920, background: LIME }} />
      </AbsoluteFill>
    );
  if (kind === "split")
    // as duas metades fecham e ficam: a cena seguinte é verde
    return t >= at ? null : (
      <AbsoluteFill style={z}>
