          <svg width={600} height={760} viewBox="-300 -380 600 760" style={{ position: "absolute", overflow: "visible" }}>
            <ellipse rx={215} ry={315} fill="none" stroke="rgba(155,255,0,0.16)" strokeWidth={54} />
