  ["Oi! Vi o evento de vocês. Faço a arte do próximo?", true, 0.25],
  ["Quanto fica?", false, 0.95],
  ["Fechado! ✓", false, 1.6],
];
export const Arsenal: React.FC<{ t: number }> = ({ t }) => {
  if (t < 12.2) {
    return (
      <AbsoluteFill style={{ background: LIME }}>
        <Col top={640} style={{ transform: `scale(${(1 + lin(t, 11.3, 12.2) * 0.05).toFixed(4)})` }}>
          <L t={t} size={176} color="#000" shadow={false} words={[["E", 11.21], ["não", 11.27], ["para", 11.41]]} />
          <L t={t} size={300} color="#000" shadow={false} words={[["por", 11.59], ["aí!", 11.71]]} />
          <div style={{ width: 760, height: 16, background: "#000", marginTop: 18, transform: `scaleX(${io(t, v(11.71), 0.25)})` }} />
        </Col>
      </AbsoluteFill>
    );
  }
  const cur = IT.reduce((acc, at, i) => (t >= at ? i : acc), -1);
  if (cur < 0) {
    return (
      <>
        <Bg t={t} y={46} a={0.16} />
        <Col top={690} style={{ transform: `scale(${(1 + lin(t, 12.2, IT[0]) * 0.04).toFixed(4)})` }}>
          <L t={t} size={92} words={[["você", 12.15], ["também", 12.31], ["recebe", 12.51]]} />
          <L t={t} size={196} color={LIME} words={[["um", 12.85], ["arsenal", 12.95]]} />
          <Handle w={760} p={io(t, v(12.95) + 0.08, 0.35)} style={{ marginTop: 20 }} />
        </Col>
      </>
    );
  }
  const at = IT[cur];
  const e = k(t, at, 0.3);
  const life = lin(t, at, cur < 4 ? IT[cur + 1] : 19.7);
  // cada item entra de um jeito
  const enter = [
    `scale(${(0.6 + 0.4 * pop(t, at, 0.3)).toFixed(3)})`,
    `translateX(${((1 - e) * 900).toFixed(1)}px)`,
    `rotateX(${((1 - e) * -80).toFixed(1)}deg)`,
    `translateY(${((1 - e) * 900).toFixed(1)}px)`,
    `scale(${(1 + (1 - e) * 0.7).toFixed(3)})`,
  ][cur];
  const hits = [v(18.28), v(18.66), v(18.9)];
  const clients = hits.filter((h) => t >= h).length;
  const P = IT[4];
  return (
    <>
      <Bg t={t} y={50} a={0.13} />
      <div style={{ position: "absolute", left: 120, top: 350, width: 840, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div style={{ fontFamily: MONO, fontWeight: 700, fontSize: 40, color: LIME, letterSpacing: "0.1em" }}>{"// ARSENAL"}</div>
        <div style={{ display: "flex", gap: 12 }}>
          {IT.map((_, i) => (
            <div key={i} style={{ width: i === cur ? 70 : 26, height: 26, borderRadius: 13, background: i <= cur ? LIME : "#333", boxShadow: i === cur ? glow(LIME, 0.5) : undefined }} />
          ))}
        </div>
      </div>
      <AbsoluteFill style={{ perspective: 1500, perspectiveOrigin: "50% 50%" }}>
        <div style={{ position: "absolute", left: 120, top: 470, width: 840, height: 1020, borderRadius: 40, background: PANEL, border: `4px solid ${LIME}`, boxSizing: "border-box", overflow: "hidden", boxShadow: `0 0 26px rgba(155,255,0,0.35), 0 40px 90px rgba(0,0,0,0.7)`, transform: `${enter} scale(${(1 + life * (cur === 4 ? 0.05 : 0.025)).toFixed(4)})`, opacity: Math.min(1, e * 4) }}>
          <div style={{ position: "absolute", left: 40, top: 30, fontFamily: MONO, fontWeight: 700, fontSize: 46, color: LIME }}>0{cur + 1}</div>
          {cur === 0 ? (
            <div style={{ position: "absolute", left: 60, top: 120, width: 712, height: 640, borderRadius: 26, background: "repeating-conic-gradient(#2e2e2e 0% 25%, #222 0% 50%) 0 0 / 60px 60px" }}>
              {SHAPES.map((d, i) => (
                <svg key={i} width={230} height={230} viewBox="0 0 24 24" style={{ position: "absolute", left: [40, 440, 240, 40, 440][i], top: [30, 40, 205, 380, 380][i], transform: `rotate(${(Math.sin(t * 3 + i) * 18).toFixed(1)}deg) translateY(${(Math.cos(t * 4 + i * 1.7) * 16).toFixed(1)}px) scale(${pop(t, at + 0.05 + i * 0.05, 0.3).toFixed(3)})`, filter: `drop-shadow(0 0 14px ${SHAPE_C[i]})` }}>
                  <path d={d} fill={SHAPE_C[i]} />
                </svg>
              ))}
            </div>
          ) : null}
          {cur === 1 ? (
            <div style={{ position: "absolute", left: 60, top: 120, width: 712, height: 640, display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gridTemplateRows: "1fr 1fr", gap: 20 }}>
              {TEX.map((bg, i) => (
                <div key={i} style={{ borderRadius: 22, background: bg, backgroundSize: i === 0 || i === 3 ? undefined : "220% 220%", backgroundPosition: `${(50 + Math.sin(t * 3 + i) * 50).toFixed(0)}% ${(50 + Math.cos(t * 2.4 + i) * 50).toFixed(0)}%`, transform: `scale(${pop(t, at + 0.05 + i * 0.05, 0.3).toFixed(3)})`, border: "2px solid rgba(255,255,255,0.18)" }} />
              ))}
            </div>
          ) : null}
          {cur === 2 ? (
            <>
              <div style={{ position: "absolute", left: 0, right: 0, top: 110, height: 460, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONTS[Math.floor(t * 7) % 5], fontSize: 380, color: LIME, textShadow: glow(LIME, 0.7), lineHeight: 1 }}>Aa</div>
              <div style={{ position: "absolute", left: 60, right: 60, top: 630, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                {FONTS.map((f, i) => (
                  <div key={i} style={{ fontFamily: f, fontSize: i === 2 ? 50 : 62, color: Math.floor(t * 7) % 5 === i ? LIME : "#8A8A8A" }}>Elite</div>
                ))}
              </div>
            </>
          ) : null}
          {cur === 3 ? (
            <>
              <div style={{ position: "absolute", left: 60, top: 120, width: 712, height: 500, borderRadius: 26, overflow: "hidden", background: "#000" }}>
                <Img src={art(26)} style={{ width: 712, height: 500, objectFit: "cover", filter: "brightness(0.4) blur(3px)", transform: `scale(${(1.1 + life * 0.1).toFixed(3)})` }} />
                <div style={{ position: "absolute", left: 266, top: 160, width: 180, height: 180, borderRadius: 90, background: LIME, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: glow(LIME, 0.9), transform: `scale(${(pop(t, at + 0.1, 0.3) * (1 + Math.sin(t * 8) * 0.05)).toFixed(3)})` }}>
                  <svg width={84} height={84} viewBox="0 0 24 24">
                    <path d="M7 4l13 8-13 8z" fill="#000" />
                  </svg>
                </div>
              </div>
              <div style={{ position: "absolute", left: 60, top: 656, width: 712, height: 18, borderRadius: 9, background: "#333" }}>
                <div style={{ width: `${(life * 62).toFixed(1)}%`, height: 18, borderRadius: 9, background: LIME }} />
              </div>
              <div style={{ position: "absolute", left: 60, top: 700, fontFamily: MONO, fontWeight: 500, fontSize: 38, color: "#B5B5B5" }}>Do PSD à arte final</div>
            </>
          ) : null}
          {cur === 4 ? (
            <>
              <div style={{ position: "absolute", left: 60, top: 120, width: 712, display: "flex", flexDirection: "column", gap: 18 }}>
                {MSGS.map(([txt, mine, d], i) =>
                  t < P + d ? null : (
                    <div key={i} style={{ alignSelf: mine ? "flex-end" : "flex-start", maxWidth: 600, background: mine ? LIME : "#333", color: mine ? "#000" : WHITE, borderRadius: 30, borderBottomRightRadius: mine ? 6 : 30, borderBottomLeftRadius: mine ? 30 : 6, padding: "18px 28px", fontFamily: MONO, fontWeight: 700, fontSize: 38, lineHeight: 1.2, transform: `scale(${pop(t, P + d, 0.3).toFixed(3)})`, transformOrigin: mine ? "100% 100%" : "0 100%" }}>{txt}</div>
                  ),
                )}
              </div>
              {t > P + 1.6 ? null : (
                <div style={{ position: "absolute", left: 76, top: t < P + 0.95 ? 330 : 424, display: "flex", gap: 10, opacity: t > P + 0.45 && !(t > P + 0.95 && t < P + 1.1) ? 1 : 0 }}>
                  {[0, 1, 2].map((i) => (
                    <div key={i} style={{ width: 16, height: 16, borderRadius: 8, background: "#8A8A8A", transform: `translateY(${(Math.sin(t * 14 - i * 1.1) * 6).toFixed(1)}px)` }} />
                  ))}
                </div>
              )}
              <div style={{ position: "absolute", left: 60, top: 560, width: 712, height: 230, borderRadius: 26, background: "#0C0C0C", border: `2px solid ${EDGE}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 36px" }}>
                <div>
                  <div style={{ fontFamily: MONO, fontWeight: 700, fontSize: 30, color: "#B5B5B5", letterSpacing: "0.08em", marginBottom: 18 }}>NOVOS CLIENTES</div>
                  <div style={{ display: "flex", gap: 16 }}>
                    {[0, 1, 2].map((i) => (
                      <div key={i} style={{ width: 92, height: 92, borderRadius: 46, background: clients > i ? LIME : "#333", display: "flex", alignItems: "flex-end", justifyContent: "center", overflow: "hidden", boxShadow: clients > i ? glow(LIME, 0.6) : undefined, transform: `scale(${(1 + bump(t, hits[i], 0.25, 0.3)).toFixed(3)})` }}>
                        <div style={{ width: 54, height: 34, borderRadius: "28px 28px 0 0", background: clients > i ? "#000" : "#666", position: "relative" }}>
                          <div style={{ position: "absolute", left: 11, top: -34, width: 32, height: 32, borderRadius: 16, background: clients > i ? "#000" : "#666" }} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
                <div style={{ fontFamily: ANTON, fontSize: 200, lineHeight: 1, color: LIME, textShadow: glow(LIME, 0.8), transform: `scale(${(1 + hits.reduce((s, h) => s + bump(t, h, 0.2), 0)).toFixed(3)})` }}>+{clients}</div>
              </div>
            </>
          ) : null}
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 44, textAlign: "center", fontFamily: ANTON, fontSize: cur === 4 ? 82 : 116, lineHeight: 1.05, color: WHITE, letterSpacing: "0.01em", whiteSpace: "nowrap" }}>{IT_NAME[cur]}</div>
        </div>
      </AbsoluteFill>
    </>
  );
};

